---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})

-- The Alienware AW2725QF is connected by both DisplayPort and HDMI. Without this,
-- Hyprland treats the two cables as two side-by-side screens (3840 px wide) and the
-- cursor drifts onto the invisible HDMI "screen". HDMI now mirrors DisplayPort, so
-- the desktop is exactly one 1920x1080 screen whichever input the monitor shows.
-- arclight: machine-specific (the author's dual-monitor DP-1 + HDMI-A-1 setup), off on this machine:
-- hl.monitor({
--     output   = "HDMI-A-1",
--     mode     = "preferred",
--     position = "auto",
--     scale    = "1",
--     mirror   = "DP-1",
-- })


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "ghostty"   -- was kitty; kitty stays installed as a fallback
local fileManager = "thunar"
local menu        = "wofi --show drun"
local locker      = "pidof hyprlock || hyprlock"
local powermenu   = "~/.local/bin/shellctl power"      -- shell-aware: arthur-shell power menu, or DMS's under DMS; old wofi script kept at ~/.config/waybar/scripts/powermenu.sh
-- Every shell action goes through ~/.local/bin/shellctl, which routes to whichever shell is running
-- (arthur-shell or DankMaterialShell). Switch shells with ~/.local/bin/shell-switch arthur|dms.
local shellctl    = "~/.local/bin/shellctl "


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE")
    -- Wallpaper: awww (the renamed swww) -- animated transitions. hyprpaper.conf is kept
    -- on disk as a fallback. --restore re-applies the saved wallpaper (waits up to 6s for
    -- the daemon).
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("~/.local/bin/wallpaper --restore")
    -- DankMaterialShell replaces waybar (bar), nwg-dock (dock) and mako (notifications).
    -- Their configs are left on disk for rollback:
    --   ~/.config/waybar/  ~/.config/nwg-dock-hyprland/  ~/.config/mako/
    hl.exec_cmd("dms run")   -- shell-switch:exec (this line is rewritten by ~/.local/bin/shell-switch)
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("hypridle")
    -- Clipboard history for arthur-shell's clipboard picker (SUPER+X). One watcher stores text
    -- and images in ~/.cache/cliphist/db. Harmless under DMS too (DMS keeps its own history).
    hl.exec_cmd("wl-paste --watch cliphist store")
    hl.exec_cmd("hyprctl setcursor phinger-cursors-light 24")
end)


