-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 4,
        gaps_out = 10,

        border_size = 2,

        col = {
            -- Focus ring is THE accent on this surface: accent-bright -> accent -> accent-dim.
            -- The gradient sweeps ONCE when a window takes focus ("borderangle" style=once,
            -- below): a light passing across the glass, with no per-frame redraw afterwards.
            active_border   = { colors = { "rgba(5a9bffee)", "rgba(2f7cffee)", "rgba(1e5bccee)" }, angle = 45 },
            -- Unfocused panes get a LIGHT hairline (text-primary at ~14%), not a navy one:
            -- glass without a light edge reads as a smudge. Measured over the wallpaper it is
            -- a faint bright rim; over a white window it disappears politely.
            inactive_border = "rgba(e6ecfa24)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 10,
        rounding_power = 2,   -- squircle exponent: this is why the corners look right

        -- Glass (pass 3). Pass 2 ran 0.97 / 0.88: measured over the wallpaper that is
        -- indistinguishable from opaque. 0.94 / 0.84 lets the blurred backdrop through
        -- on every pane; the focused one stays readable, unfocused ones frost.
        active_opacity     = 0.94,
        inactive_opacity   = 0.84,
        fullscreen_opacity = 1.0,   -- never frost a fullscreen window

        -- Push unfocused windows back so focus reads without a loud border.
        dim_inactive = true,
        dim_strength = 0.10,
        dim_around   = 0.40,

        -- Depth comes from shadow, not from blur alone: deep near-black, moderate alpha,
        -- dropped slightly so panes sit ABOVE what is behind them. Unfocused panes cast a
        -- lighter shadow, so the focused one visibly floats highest.
        shadow = {
            enabled        = true,
            range          = 24,
            render_power   = 3,
            color          = 0xb0050810,   -- shadow token @ 0.69
            color_inactive = 0x78050810,   -- shadow token @ 0.47
            offset         = { 0, 4 },
        },

        -- Faint accent halo on the focused window only. Deliberately barely visible.
        glow = {
            enabled        = true,
            range          = 8,
            render_power   = 3,
            color          = "rgba(2f7cff40)",
            color_inactive = "rgba(00000000)",
        },

        blur = {
            enabled   = true,
            size      = 8,
            passes    = 3,        -- cost is ~quadratic in passes: drop to 2 first if it stutters
            noise     = 0.015,    -- grain stops blur looking like a plastic smear
            contrast  = 1.05,
            brightness = 0.95,    -- glass sits a touch darker than what it covers: reads as depth
            vibrancy  = 0.24,     -- keeps colour in the glass over dark navy ...
            vibrancy_darkness = 0.4,   -- ... but only where the backdrop is actually dark
            popups    = true,
            popups_ignorealpha = 0.2,
            new_optimizations = true,
            special   = true,     -- the scratchpad frosts what is under it too
            -- xray OFF (pass 3). A/B measured 2026-09-21, navy float over a white window:
            --   xray on : unfocused navy pane = (9,13,26)  -> the white window behind it
            --             contributes NOTHING; every pane looks like a flat cut-out of wallpaper.
            --   xray off: unfocused navy pane = (34,37,49) -> the pane visibly sits OVER the
            --             window behind it. That is the depth that was missing.
            xray      = false,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Border colours rendered by theme-apply (fixed palettes) or matugen (dynamic mode).
-- Must come AFTER the block above or the static colours win. pcall: if the generated
-- file is ever missing, the static colours above stay and login is unaffected.
local okColors, rice = pcall(require, "generated-colors")
if not okColors or type(rice) ~= "table" then
    -- Built-in Midnight Blue fallback: the desktop stays correct even with no generated file.
    rice = { surface = "121b32", text_secondary = "a8b6d4", border_strong = "3a4e7a", bg_base = "0a0f1e",
             accent = "2f7cff", accent_bright = "5a9bff", error = "ff5c6e" }
end

-- Default curves and animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })

-- Motion (pass 3): liquid, not springy. Every curve below is a bezier that starts fast and
-- settles without overshoot (no bounce, no cartoon). The pass-2 springs are kept for reference.
--   liquid   easeOutQuint-like: windows appear/settle          {0.22,1} {0.36,1}
--   glide    easeInOut, gentle both ends: moves and workspaces {0.40,0} {0.20,1}
--   softOut  easeOutExpo: fades and layers                     {0.16,1} {0.30,1}
hl.curve("liquid",         { type = "bezier", points = { {0.22, 1},  {0.36, 1} } })
hl.curve("glide",          { type = "bezier", points = { {0.40, 0},  {0.20, 1} } })
hl.curve("softOut",        { type = "bezier", points = { {0.16, 1},  {0.30, 1} } })
-- Springs (unused since pass 3; zeta = dampening / (2*sqrt(stiffness*mass)), < 1 overshoots).
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })
hl.curve("springLiquid",   { type = "spring", mass = 1, stiffness = 170,      dampening = 18.5 })
hl.curve("springGlide",    { type = "spring", mass = 1, stiffness = 140,      dampening = 16.2 })

-- speed unit = 100 ms. Everything lands inside ~350 ms so the desktop still feels fast.
hl.animation({ leaf = "global",           enabled = true,  speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",           enabled = true,  speed = 4,    bezier = "softOut" })
hl.animation({ leaf = "windows",          enabled = true,  speed = 3.2,  bezier = "liquid" })
hl.animation({ leaf = "windowsIn",        enabled = true,  speed = 3.0,  bezier = "liquid",       style = "popin 92%" })   -- slight scale + fade in
hl.animation({ leaf = "windowsOut",       enabled = true,  speed = 2.0,  bezier = "softOut",      style = "popin 94%" })
hl.animation({ leaf = "windowsMove",      enabled = true,  speed = 3.2,  bezier = "glide" })
hl.animation({ leaf = "fadeIn",           enabled = true,  speed = 2.2,  bezier = "softOut" })
hl.animation({ leaf = "fadeOut",          enabled = true,  speed = 1.8,  bezier = "softOut" })
hl.animation({ leaf = "fade",             enabled = true,  speed = 2.6,  bezier = "softOut" })
hl.animation({ leaf = "fadeDim",          enabled = true,  speed = 3.0,  bezier = "softOut" })   -- dim_inactive transitions
hl.animation({ leaf = "fadeShadow",       enabled = true,  speed = 3.0,  bezier = "softOut" })
hl.animation({ leaf = "layers",           enabled = true,  speed = 2.8,  bezier = "softOut" })
hl.animation({ leaf = "layersIn",         enabled = true,  speed = 2.6,  bezier = "softOut",      style = "fade" })       -- layer surfaces fade, never pop
hl.animation({ leaf = "layersOut",        enabled = true,  speed = 1.8,  bezier = "softOut",      style = "fade" })
hl.animation({ leaf = "fadeLayersIn",     enabled = true,  speed = 2.2,  bezier = "softOut" })
hl.animation({ leaf = "fadeLayersOut",    enabled = true,  speed = 1.6,  bezier = "softOut" })
hl.animation({ leaf = "workspaces",       enabled = true,  speed = 3.4,  bezier = "glide",        style = "slidefade 20%" })   -- short slide + fade: subtle parallax feel
hl.animation({ leaf = "specialWorkspace", enabled = true,  speed = 3.4,  bezier = "glide",        style = "slidefadevert 20%" })
hl.animation({ leaf = "zoomFactor",       enabled = true,  speed = 5,    bezier = "softOut" })
-- Border sweep: ONCE per focus change, not a loop. The loop was measured in pass 2 at
-- +13.5 percentage points of GPU continuously (330 Hz redraw). "once" plays the 45deg
-- gradient sweep when focus lands and then stops, so idle cost is zero.
hl.animation({ leaf = "borderangle",      enabled = true,  speed = 8,    bezier = "softOut",      style = "once" })

