hl.bind(mainMod .. " + Tab", hl.dsp.exec_cmd(shellctl .. "overview"))

-- Windows
hl.bind("CTRL + ALT + Q",      hl.dsp.window.close())
hl.bind("CTRL + ALT + V",      hl.dsp.window.float({ action = "toggle" }))
hl.bind("CTRL + ALT + F",      hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + F",     hl.dsp.window.fullscreen())
hl.bind("CTRL + ALT + J",      hl.dsp.layout("togglesplit"))
hl.bind("CTRL + ALT + left",   hl.dsp.focus({ direction = "left" }))
hl.bind("CTRL + ALT + right",  hl.dsp.focus({ direction = "right" }))
