-- "Minimize": send focused window to the special workspace, toggle it back into view
hl.bind("CTRL + ALT + M",      hl.dsp.window.move({ workspace = "special:magic", follow = false }))
hl.bind("CTRL + ALT + S",      hl.dsp.workspace.toggle_special("magic"))

-- Workspaces: Ctrl+Alt+[0-9] switch, Ctrl+Alt+Shift+[0-9] move window
for i = 1, 10 do
    local key = i % 10
    hl.bind("CTRL + ALT + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind("CTRL + ALT + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Screenshots (region -> clipboard, full -> ~/Pictures/Screenshots)
-- Screenshots: every capture -> ~/Pictures/Screenshots/<timestamp>.png AND the
-- clipboard, then a thumbnail notification (Open / Copy / Annotate).
-- Script: ~/.local/bin/shot (themed from ~/.config/theme/tokens). Same keys as before.
