----------------------------------
---- MIDNIGHT BLUE: LAYER RULES ----
----------------------------------
-- Blur behind wofi (launcher, sudo askpass popup, screenshot menu, wallpaper picker).
-- Namespaces verified live with `hyprctl layers` while each surface was open (2026-09-21):
--   wofi                         -> "wofi"
--   DMS bar / spotlight / power menu / control centre / notifications / dash ->
--     "dms:bar", "dms:spotlight", "dms:power-menu", "dms:control-center" (+ ":background"),
--     "dms:notification-popup", "dms:dash" (+ ":background")
-- The old "logout_dialog" entry was wlogout's namespace; wlogout is no longer installed and
-- DMS's power menu replaced it, so that rule now points at "dms:power-menu" instead of at nothing.
--
-- DMS blurs its own surfaces through ext-background-effect-v1 (Hyprland advertises it; DMS's
-- BlurService probes it and publishes blur regions). The compositor-side rules for the DMS
-- namespaces below are therefore belt-and-braces: measured in pass 2 they neither added nor
-- removed blur. ignore_alpha keeps fully transparent margins from being blurred.
local blurLayers = {
    { key = "wofi",         ns = "^wofi$",            ignore = 0.2  },
    { key = "power_menu",   ns = "^dms:power-menu$",  ignore = 0.15 },
    { key = "spotlight",    ns = "^dms:spotlight$",   ignore = 0.15 },
    { key = "notification", ns = "^dms:notification-popup$", ignore = 0.15 },
    { key = "control_center", ns = "^dms:control-center$", ignore = 0.15 },
    -- arthur-shell: every surface has its own namespace. The shell publishes an exact
    -- rounded blur region itself (ext-background-effect); measured 2026-09-21, these rules
    -- neither add a second blur nor blur the transparent shadow margin (stripe std-dev
    -- identical with and without, ignore_alpha 0.15 and 0.35). Kept as belt-and-braces.
    { key = "arthur",       ns = "^arthur-(bar|dock|panel|launcher|notifs|osd|power|picker|overview|clipboard|menu)$", ignore = 0.15 },
}

for _, l in ipairs(blurLayers) do
    hl.layer_rule({
        name  = "blur-" .. l.key,
        match = { namespace = l.ns },
        blur         = true,
        ignore_alpha = l.ignore,
    })
end

-- arthur-shell modal surfaces dim what is behind them (power menu, overview).
hl.layer_rule({
    name       = "dim-arthur-modals",
    match      = { namespace = "^arthur-(power|overview)$" },
    dim_around = true,
})

hl.window_rule({
    name  = "float-pavucontrol",
    match = { class = "^(org.pulseaudio.pavucontrol)$" },
    float = true,
    size  = "900 600",
    center = true,
})

-------------------------------------------------
---- MIDNIGHT BLUE: GLASS OPACITY PER APP ----
-------------------------------------------------
-- Global glass is active 0.94 / inactive 0.84. Apps where I read small text sit a step
-- above that (0.96 focused / 0.86 unfocused) so text stays crisp while the pane is still
-- visibly glass. Pass 2 had these at 1.0 focused: the window looked at 90% of the day
-- was the one that was never glass. "override" makes the value absolute; without it the
-- rule MULTIPLIES with the global opacity. (Ghostty adds its own 0.85 background alpha.)
for i, cls in ipairs({ "^com.mitchellh.ghostty$", "^kitty$", "^dev.zed.Zed$", "^zen$" }) do
    hl.window_rule({
        name    = "readable-opacity-" .. i,
        match   = { class = cls },
        opacity = "0.96 override 0.86 override",
    })
end

-- Never frost or dim fullscreen content (video, games, presentations).
hl.window_rule({
    name    = "fullscreen-crisp",
    match   = { fullscreen = true },
    opacity = "1.0 override 1.0 override",
    no_dim  = true,
})

-- Picture-in-Picture video (Zen): floating, pinned, never dimmed or frosted.
hl.window_rule({
    name              = "pip",
    match             = { title = "^Picture-in-Picture$" },
    float             = true,
    pin               = true,
    keep_aspect_ratio = true,
    size              = "480 270",
    move              = "100%-500 60",
    opacity           = "1.0 override 1.0 override",
    no_dim            = true,
})


