-------------------------------------------------
---- GAMES: KEEP TILING OUT OF THEIR WAY ----
-------------------------------------------------
-- The problem this fixes: a game asks for fullscreen, the dwindle layout keeps
-- re-tiling it to a size of the layout's choosing, the two argue about the
-- window size, and you end up staring at a black screen.
--
-- The fix is to take game windows out of the tiling layout completely (float),
-- and strip every decoration that changes their size or redraws their surface.
-- The game then owns its own geometry and fullscreen just works.
--
-- To cover a game that isn't caught below, add its window class to this list.
-- To find the class: launch the game, then run  hyprctl clients | grep class
local gameClasses = {
    "^steam_app_[0-9]+$",           -- every Steam/Proton game, incl. Geometry Dash (322170)
    "^gamescope$",                  -- anything launched through gamescope
    "^(GeometryDash|Geometry Dash)$", -- a native / non-Steam build
}

for i, gameClass in ipairs(gameClasses) do
    hl.window_rule({
        name  = "game-no-tiling-" .. i,
        match = { class = gameClass },

        float       = true,   -- out of the tiling layout: nothing left to fight over
        no_max_size = true,   -- never clamp the size the game asks for

        -- hyprbars' title bar is "part of the window" (bar_part_of_window), so it
        -- eats 26px of the game's drawing area and the game never gets the size it
        -- asked for. That mismatch is a prime black-screen source on XWayland games.
        ["hyprbars:no_bar"] = true,

        -- Decoration that resizes or re-renders the surface -> artifacts / black frames.
        border_size = 0,
        rounding    = 0,
        no_blur     = true,
        no_shadow   = true,
        no_anim     = true,   -- don't animate the jump into fullscreen

        content      = "game",       -- mark the surface as a game
        idle_inhibit = "fullscreen", -- no lock screen / screen blank mid-run

        -- Lower input latency, at the cost of visible tearing. Needs
        -- general.allow_tearing = true up in LOOK AND FEEL as well.
        -- immediate = true,
    })
end


-- Games stay fully opaque and undimmed even when windowed or unfocused. This is a
-- separate rule on the same gameClasses list so the game block above is untouched.
for i, gameClass in ipairs(gameClasses) do
    hl.window_rule({
        name    = "game-opaque-" .. i,
        match   = { class = gameClass },
        opacity = "1.0 override 1.0 override",
        no_dim  = true,
    })
end


