-- The settings app writes ~/.config/hypr/arthur-generated.lua (appearance + animation
-- overrides), validates it with `hyprctl reload` + `hyprctl configerrors`, and restores
-- the previous file if anything errors. This file stays hand-owned; pcall means a
-- missing or broken generated file can never stop Hyprland loading.
local okArthur, arthurErr = pcall(require, "arthur-generated")
if not okArthur and not tostring(arthurErr):find("not found") then
    hl.notification.create({ text = "arthur-generated.lua failed to load: " .. tostring(arthurErr), timeout = 8000 })
end

-- arclight:begin  (added by Arclight; delete this block to go back to plain Hyprland)
-- The AI-native layer: new binds (Super+Shift+A ask, Super+I settings), autostart of the
-- session daemon, accessibility env, the window glow. Source: /usr/share/arclight/hypr/arclight.lua
-- (copy it to ~/.config/hypr/arclight.lua to customise).
package.path = package.path .. ";/src/desktop/hypr/?.lua"
-- `hyprctl reload` re-runs this file in the same Lua state: drop cached modules so they run again
for _, m in ipairs({ "arclight", "arclight-colors", "arclight-settings" }) do package.loaded[m] = nil end
local okArc, arcErr = pcall(require, "arclight")
if not okArc then
    hl.notification.create({ text = "Arclight layer failed to load: " .. tostring(arcErr), timeout = 10000 })
end
-- Values set with `arc set` / Arclight Settings. Loaded last so they win.
pcall(require, "arclight-settings")
